    async def list_node_types(
        self,
        *,
        include_disabled_types: bool,
        zone: str | None = None,
        page: Int32Value | None = None,
        page_size: int | None = None,
    ) -> ListNodeTypesResponse:
        """
        List available node types

        List all available node types. By default, the node types returned in the list
        are ordered by creation date in ascending order, though this can be modified via
        the `order_by` field.

        Args:
            zone: The zone you want to target
            include_disabled_types: Defines whether or not to include disabled types.
        """
        data = await self._client.request_json(
            "GET",
            self._client.path(
                "/redis/v1/zones/{zone}/node-types", zone=self._client.zone(zone)
            ),
            params={
                "include_disabled_types": include_disabled_types,
                "page": page,
                "page_size": page_size,
            },
        )
        return ListNodeTypesResponse.model_validate(data)

    async def list_node_types_iter(
        self,
        *,
        include_disabled_types: bool,
        zone: str | None = None,
        page_size: int | None = None,
    ) -> AsyncIterator[NodeType]:
        """Iterate over every item of `list_node_types`, page after page."""

        async def fetch(page: int) -> tuple[ListNodeTypesResponse, int | None]:
            response = await self._client.request(
                "GET",
                self._client.path(
                    "/redis/v1/zones/{zone}/node-types", zone=self._client.zone(zone)
                ),
                params={
                    "include_disabled_types": include_disabled_types,
                    "page": page,
                    "page_size": page_size,
                },
            )
            result = ListNodeTypesResponse.model_validate(response.json())
            return result, result.total_count

        async for entry in paginate(
            fetch,
            lambda page: page[0].node_types or [],
            lambda page: page[1],
        ):
            yield entry

    async def list_node_types_all(
        self,
        *,
        include_disabled_types: bool,
        zone: str | None = None,
        page_size: int | None = None,
    ) -> list[NodeType]:
        """Every item of `list_node_types`, all pages read."""
        return [
            entry
            async for entry in self.list_node_types_iter(
                include_disabled_types=include_disabled_types,
                zone=zone,
                page_size=page_size,
            )
        ]
